  /** Credential type. Prefer KUBECONFIG. Use SERVICE_ACCOUNT_TOKEN as fallback. */
  credentialType: RegisterClusterRequestCredentialType;
  /** kubeconfig YAML content. Required when credentialType is KUBECONFIG. */
  kubeconfig?: string;
  /** ServiceAccount token credential. Required when credentialType is SERVICE_ACCOUNT_TOKEN. */
  serviceAccount?: ServiceAccountCredentialRequest;
  /** Namespace access settings */
